<?php require_once 'config.php'; if ($_SERVER['REQUEST_METHOD']==='POST') { $name=trim($_POST['name']??''); $email=trim($_POST['email']??''); $phone=trim($_POST['phone']??''); $p=$_POST['password']??''; $c=$_POST['confirm']??''; if ($p!==$c) flash('Passwords do not match.'); else { try { $hash=password_hash($p,PASSWORD_DEFAULT); $role='user'; $s=db()->prepare('INSERT INTO users(full_name,name,email,phone,password_hash,password,role) VALUES(?,?,?,?,?,?,?)'); $s->bind_param('sssssss',$name,$name,$email,$phone,$hash,$hash,$role); $s->execute(); flash('Registration successful. Please login.'); redirect('login.php'); } catch (mysqli_sql_exception $e) { flash('This email is already registered. Use another email.'); } } }
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Register</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="auth-wrap register"><section class="auth-banner"><div class="brand-big">🍴</div><h1>Smart Canteen<br>Ordering System</h1><p>Create your account</p></section><form class="auth-card" method="post"><h2>Register</h2><p>Create a new account</p><?php if($m=flash()):?><div class="error"><?=h($m)?></div><?php endif;?><label>Full Name<input name="name" required placeholder="Enter your full name"></label><label>Email<input type="email" name="email" required placeholder="Enter your email"></label><label>Phone Number<input name="phone" required placeholder="Enter your phone number"></label><label>Password<input type="password" name="password" required minlength="4" placeholder="Create a password"></label><label>Confirm Password<input type="password" name="confirm" required placeholder="Confirm your password"></label><button>Register</button><p>Already have an account? <a href="login.php">Login here</a></p></form></div></body></html>
